// SIMULACIÓN (no es una red): un emisor manda 5 segmentos de 1.000 bytes y el 3.º se pierde.
// Las posiciones cuentan bytes desde 1, como en la captura relativa de tcpdump.
const segmentos = [];
for (let i = 0; i < 5; i++) segmentos.push({ seq: 1 + i * 1000, largo: 1000 });

const llegadas = segmentos.filter((s, i) => i !== 2);   // el 3.º se pierde...
llegadas.push(segmentos[2]);                            // ...y llega recién cuando el emisor lo reenvía

let esperado = 1;                // el próximo byte que el receptor necesita
const guardados = new Map();     // segmentos que llegaron "adelantados"
for (const s of llegadas) {
  guardados.set(s.seq, s.largo);
  const antes = esperado;
  while (guardados.has(esperado)) {          // avanza mientras no haya huecos
    const largo = guardados.get(esperado);
    guardados.delete(esperado);
    esperado += largo;
  }
  const nota = esperado === antes ? "(hay un hueco: repite el mismo ACK)" : "";
  console.log(`llegan los bytes ${s.seq} a ${s.seq + s.largo - 1} -> ACK ${esperado} ${nota}`);
}
